#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string P;
    cin >> N >> P;

    vector<array<int, 26>> pref(N + 1);
    pref[0].fill(0);

    for (int i = 0; i < N; ++i) {
        pref[i + 1] = pref[i];
        ++pref[i + 1][P[i] - 'a'];
    }

    for (int len = 1; len < N; ++len) {
        if (N % len != 0) continue;

        int blocks = N / len;
        bool valid = true;

        for (int j = 2; j <= blocks && valid; ++j) {
            int boundary = j * len;
            for (int c = 0; c < 26; ++c) {
                if (pref[boundary][c] != j * pref[len][c]) {
                    valid = false;
                    break;
                }
            }
        }

        if (valid) {
            cout << P.substr(0, len) << '\n';
            return 0;
        }
    }

    cout << "*\n";
    return 0;
}
